# Explicit, bounded example. Production Action run logs also enforce run ownership.
import json, os, pathlib, zipfile
root = pathlib.Path(os.environ['MUSTRA_PARAM_log_directory'])
job = os.environ['MUSTRA_PARAM_job_id']
if not job:
    raise ValueError('An endpoint run ID is required')
rows = []
scanned = 0
for path in sorted(root.iterdir()):
    if path.suffix not in ('.log', '.zip'):
        continue
    archive = zipfile.ZipFile(path) if path.suffix == '.zip' else None
    streams = [archive.open(n) for n in archive.namelist()] if archive else [path.open('rb')]
    try:
        for stream in streams:
            with stream:
                for line in stream:
                    scanned += len(line)
                    if scanned > 16 * 1024 * 1024:
                        raise ValueError('Example scan exceeds 16 MB; use the built-in log sensor')
                    event = json.loads(line)
                    if event.get('job_id') == job:
                        rows.append({'value': str(event.get('stage', '')) + ': ' + str(event.get('message', ''))[:400]})
                        rows = rows[-50:]
    finally:
        if archive:
            archive.close()
print(json.dumps(rows))

